#include <stdio.h>

#define MAX(a,b) a > b ? a : b

int getResult(int n, int nums[], int m);

int main() {
    int n;
    scanf("%d", &n);

    int nums[n];
    int idx = 0;
    while(scanf("%d", &nums[idx++])) {
        if(getchar() != ' ') break;
    }

    int m;
    scanf("%d", &m);

    printf("%d\n", getResult(n, nums, m));

    return 0;
}

int getResult(int n, int nums[], int m) {
    int sum = 0;
    for(int i=0; i<m; i++) {
        sum += nums[i];
    }

    int ans = sum;
    for(int i=1; i<=n-m; i++) {
        sum += nums[i+m-1] - nums[i-1];
        ans = MAX(ans, sum);
    }

    return ans;
}
